// Generated by MCSuperMods: the msm:components passthrough of msm_runtime as a plain helper.
package msm_test;

import com.google.gson.JsonElement;
import com.google.gson.JsonParser;
import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.JsonOps;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;
import net.minecraft.core.HolderGetter;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.Registry;
import net.minecraft.core.RegistryAccess;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.RegistryOps;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.item.Item;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Vanilla data components set from JSON (the item definition's {@code msm:components}), applied
 * before the item's other properties so those win on a clash.
 */
public final class VanillaComponents {
    /**
     * Components whose value names an element or a tag of a data pack registry, decoded once data packs are loaded.
     */
    public static final Set<Identifier> DELAYED = Set.of(
            Identifier.withDefaultNamespace("jukebox_playable"),
            Identifier.withDefaultNamespace("provides_trim_material"),
            Identifier.withDefaultNamespace("trim"),
            Identifier.withDefaultNamespace("damage_resistant"),
            Identifier.withDefaultNamespace("blocks_attacks"),
            Identifier.withDefaultNamespace("damage_type"));

    private static final Logger LOGGER = LoggerFactory.getLogger("msm_test");
    private static RegistryAccess staticRegistries;

    private VanillaComponents() {}

    /** Sets every component of {@code json} (an object from component id to value); problems are logged and the entry is skipped. */
    public static Item.Properties apply(Item.Properties props, String owner, String json) {
        for (Map.Entry<String, JsonElement> e : JsonParser.parseString(json).getAsJsonObject().entrySet()) {
            Identifier id = Identifier.parse(e.getKey());
            Optional<DataComponentType<?>> type = BuiltInRegistries.DATA_COMPONENT_TYPE.getOptional(id);
            String where = owner + ": msm:components: " + id + ": ";
            if (type.isEmpty()) {
                LOGGER.error("{}unknown data component", where);
                continue;
            }
            if (type.get().isTransient()) {
                LOGGER.error("{}not a persistent data component; not supported", where);
                continue;
            }
            props = applyOne(props, owner, id, type.get(), e.getValue(), where);
        }
        return props;
    }

    private static <T> Item.Properties applyOne(Item.Properties props, String owner, Identifier id, DataComponentType<T> type,
            JsonElement json, String where) {
        Codec<T> codec = type.codecOrThrow();
        Set<Identifier> missing = new TreeSet<>();
        DataResult<T> result = codec.parse(staticOps(missing), json);
        if (result.result().isPresent()) {
            return props.component(type, result.result().get());
        }
        if (DELAYED.contains(id)) {
            return props.delayedComponent(type, provider -> decodeLate(owner, id, codec, json, provider));
        }
        String message = result.error().map(DataResult.Error::message).orElse("invalid value");
        if (!missing.isEmpty()) {
            LOGGER.error("{}needs a data pack registry ({}); not supported ({})", where,
                    String.join(", ", missing.stream().map(Identifier::toString).toList()), message);
        } else {
            LOGGER.error("{}{}", where, message);
        }
        return props;
    }

    /** Decodes a {@link #DELAYED} component once data packs are loaded; on failure logs and leaves the component unset. */
    private static <T> T decodeLate(String owner, Identifier id, Codec<T> codec, JsonElement json, HolderLookup.Provider provider) {
        DataResult<T> result = codec.parse(RegistryOps.create(JsonOps.INSTANCE, provider), json);
        if (result.error().isPresent()) {
            LOGGER.error("{}: msm:components: {}: {}; the component is not set", owner, id, result.error().get().message());
            return null;
        }
        return result.getOrThrow();
    }

    /** Registry ops over the built-in registries that record every registry asked for and not found. */
    private static RegistryOps<JsonElement> staticOps(Set<Identifier> missing) {
        if (staticRegistries == null) {
            staticRegistries = RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);
        }
        RegistryAccess registries = staticRegistries;
        return RegistryOps.create(JsonOps.INSTANCE, new RegistryOps.RegistryInfoLookup() {
            @Override
            @SuppressWarnings("unchecked")
            public <E> Optional<HolderGetter<E>> lookup(ResourceKey<? extends Registry<? extends E>> key) {
                Optional<? extends HolderLookup.RegistryLookup<E>> found = registries.lookup(key);
                if (found.isEmpty()) {
                    missing.add(key.identifier());
                }
                return found.map(l -> (HolderGetter<E>) l);
            }
        });
    }
}
